using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B3RepairQuality {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-09_B3_StructureRepair/";static JObject Plan()=>JObject.Parse(File.ReadAllText(R+"/SourceAssets/B3_FullFloor/layout.json"));static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B3_Circular.unity"))throw new Exception("Saved B3 edit required");return s;}
 static List<Vector3> PathOf(JToken t)=>t["path"]!=null?t["path"].Select(p=>new Vector3((float)p[0],-49,-(float)p[1])).ToList():new List<Vector3>{new Vector3((float)t["p"][0],-49,-(float)t["p"][1]),new Vector3((float)t["q"][0],-49,-(float)t["q"][1])};
 static Vector3 At(List<Vector3> p,float d,out Vector3 dir){for(int i=1;i<p.Count;i++){float len=Vector3.Distance(p[i-1],p[i]);if(d<=len){dir=(p[i]-p[i-1]).normalized;return Vector3.Lerp(p[i-1],p[i],Mathf.Clamp01(d/len));}d-=len;}dir=(p[p.Count-1]-p[p.Count-2]).normalized;return p[p.Count-1];}
 public static object Width(){var s=Check();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();bool old=cc.enabled;cc.enabled=false;Physics.SyncTransforms();var bad=new List<object>();int samples=0;float minCeiling=1000;try{foreach(var t in Plan()["tunnels"]){var path=PathOf(t);float total=0;for(int i=1;i<path.Count;i++)total+=Vector3.Distance(path[i-1],path[i]);int count=Mathf.CeilToInt(total/.35f);for(int i=0;i<=count;i++){float d=total*i/count;var p=At(path,d,out var dir);float width=Mathf.Lerp(.65f,1.25f,Mathf.Clamp01((Mathf.Min(d,total-d)-1.2f)/2.6f));foreach(float f in new[]{-1f,-.5f,0,.5f,1f}){var v=p+Vector3.Cross(Vector3.up,dir)*width*f;samples++;bool floor=Physics.Raycast(v+Vector3.up*.30f,Vector3.down,out var hit,.55f,~0,QueryTriggerInteraction.Ignore)&&Mathf.Abs(hit.point.y-v.y)<.12f;var hits=Physics.OverlapCapsule(v+Vector3.up*.43f,v+Vector3.up*1.50f,.32f,~0,QueryTriggerInteraction.Ignore);if(!floor||hits.Length>0)bad.Add(new{id=(string)t["id"],distance=d,offset=width*f,floor,hits=hits.Select(c=>c.name).ToArray(),point=new[]{v.x,v.y,v.z}});if(f==0&&Physics.Raycast(v+Vector3.up*.15f,Vector3.up,out var roof,30,~0,QueryTriggerInteraction.Ignore))minCeiling=Mathf.Min(minCeiling,roof.distance+.15f);}}}}finally{cc.enabled=old;Physics.SyncTransforms();}var result=new{samples,failed=bad.Count,minimumCenterHeadroom=minCeiling,failures=bad};File.WriteAllText(O+"width.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{samples,failed=bad.Count,minimumCenterHeadroom=minCeiling,failures=bad.Take(12)};}
 public static object Audit(){var s=Check();var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var rs=all.SelectMany(t=>t.GetComponents<MeshRenderer>()).ToArray();var mfs=all.SelectMany(t=>t.GetComponents<MeshFilter>()).ToArray();var bad=new List<object>();foreach(var m in mfs.Where(f=>f.sharedMesh).Select(f=>f.sharedMesh).Distinct()){if(!m.isReadable)continue;var v=m.vertices;var ix=m.triangles;int degen=0;for(int i=0;i<ix.Length;i+=3)if(Vector3.Cross(v[ix[i+1]]-v[ix[i]],v[ix[i+2]]-v[ix[i]]).sqrMagnitude<1e-16f)degen++;if(degen>0)bad.Add(new{name=m.name,degen});}var result=new{scene=s.path,saved=!s.isDirty,objects=all.Length,renderers=rs.Length,missingMeshes=mfs.Count(m=>!m.sharedMesh),missingMaterials=rs.Sum(r=>r.sharedMaterials.Count(m=>!m)),missingScripts=all.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),nonAscii=all.Count(t=>t.name.Any(c=>c>127)),lights=all.Sum(t=>t.GetComponents<Light>().Length),activeLights=all.Sum(t=>t.GetComponents<Light>().Count(l=>l.enabled&&l.gameObject.activeInHierarchy)),cctvs=all.Count(t=>t.name.EndsWith("_CCTV")),colliders=all.Sum(t=>t.GetComponents<Collider>().Length),lodGroups=all.Sum(t=>t.GetComponents<LODGroup>().Length),probes=all.Sum(t=>t.GetComponents<ReflectionProbe>().Length),meshIssues=bad};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
 static void Shot(string name,Vector3 p,Vector3 target){var go=new GameObject("B3_ReviewTemporary"){hideFlags=HideFlags.HideAndDontSave};var c=go.AddComponent<Camera>();c.transform.position=p;c.transform.LookAt(target);c.fieldOfView=84;c.nearClipPlane=.05f;c.farClipPlane=250;c.useOcclusionCulling=false;var rt=new RenderTexture(1440,900,24){antiAliasing=4};Texture2D tex=null;var old=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,900),0,0);tex.Apply();File.WriteAllBytes(O+name+".png",tex.EncodeToPNG());}finally{c.targetTexture=null;RenderTexture.active=old;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Detail(){var s=Check();var plan=Plan();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool playerActive=player.activeSelf;var lamps=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Light>(true)).Where(l=>l.transform.IsChildOf(s.GetRootGameObjects().Single(g=>g.name=="B3_Circular_SampleFloor").transform)).ToDictionary(l=>l,l=>l.enabled);try{player.SetActive(false);var tunnel=plan["tunnels"].Single(t=>(string)t["id"]=="B3-T08");var path=PathOf(tunnel);float total=(float)tunnel["length"];foreach(float d in new[]{1f,9f,18f,30f,total-9f,total-1f}){var p=At(path,d,out var dir);if(d>total/2)dir=-dir;Shot("T08_inside_"+d.ToString("0"),p+Vector3.up*1.7f,p+dir*5+Vector3.up*1.7f);}foreach(string id in new[]{"C03","C04"}){var r=plan["rooms"].Single(q=>(string)q["id"]==id);var door=r["doors"].Single(q=>(string)q["id"]=="B3-T08");var dir=new Vector3((float)door["x"],0,(float)door["z"]).normalized;var center=new Vector3((float)r["x"],-47.3f,-(float)r["v"]);Shot(id+"_T08_portal",center+dir*((float)r["r"]-4),center+dir*((float)r["r"]+3));}foreach(var l in lamps.Keys)l.enabled=true;foreach(var r in plan["rooms"].Where(r=>(string)r["kind"]!="core")){var center=new Vector3((float)r["x"],-49,-(float)r["v"]);var door=r["doors"][0];var dir=new Vector3((float)door["x"],0,(float)door["z"]).normalized;Shot("inspection_"+(string)r["id"],center+dir*((float)r["r"]-1.4f)+Vector3.up*1.7f,center+Vector3.up*1.3f);}}finally{foreach(var l in lamps)if(l.Key)l.Key.enabled=l.Value;player.SetActive(playerActive);EditorSceneManager.OpenScene(s.path);}return new{images=21,inspection="Work lights temporarily on; restored saved lighting"};}
 public static object Bake(){var s=Check();var root=s.GetRootGameObjects().Single(g=>g.name=="B3_Circular_SampleFloor");var path=PathOf(Plan()["tunnels"].Single(t=>(string)t["id"]=="B3-T08"));var area=root.transform.Find("B3_OcclusionAreas/View_B3-T08");var min=path.Aggregate(new Vector3(float.MaxValue,0,float.MaxValue),(a,b)=>Vector3.Min(a,b));var max=path.Aggregate(new Vector3(float.MinValue,-49,float.MinValue),(a,b)=>Vector3.Max(a,b));area.position=(min+max)*.5f+Vector3.up*1.8f;area.rotation=Quaternion.identity;area.GetComponent<OcclusionArea>().size=new Vector3(max.x-min.x+5,3.6f,max.z-min.z+5);var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool active=player.activeSelf;player.SetActive(false);int n=0;try{foreach(var p in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<ReflectionProbe>())){string asset=AssetDatabase.GetAssetPath(p.customBakedTexture);if(string.IsNullOrEmpty(asset)||!asset.Contains("/B3/"))throw new Exception("Invalid B3 probe path");if(!Lightmapping.BakeReflectionProbe(p,asset))throw new Exception("Bake failed");AssetDatabase.ImportAsset(asset,ImportAssetOptions.ForceSynchronousImport);p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Cubemap>(asset);n++;}}finally{player.SetActive(active);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);StaticOcclusionCulling.GenerateInBackground();return new{probes=n,occlusionRunning=StaticOcclusionCulling.isRunning};}
 public static object Closeups(){var s=Check();var root=s.GetRootGameObjects().Single(g=>g.name=="B3_Circular_SampleFloor").transform;var p=Plan();var light=new GameObject("B3_TemporaryDetailLight"){hideFlags=HideFlags.HideAndDontSave};var l=light.AddComponent<Light>();l.type=LightType.Point;l.intensity=4;l.range=8;try{foreach(string model in new[]{"BR_B3_SamplePallet_1","BR_B3_SampleDrawerIsland","BR_B3_LoadedTransferCart","BR_B3_SterileTrayRack","BR_B3_SealingKit"}){var item=p["placements"].First(q=>(string)q["model"]==model);var g=root.Find("B3_"+(string)item["room"]+"_Sector/Equipment/"+(string)item["name"]);var target=g.position+Vector3.up*((string)item["role"]=="BenchAccessory"?.12f:.8f);var pos=target+g.forward*((string)item["role"]=="BenchAccessory"?.9f:2f)+g.right*.75f+Vector3.up*.65f;light.transform.position=pos;Shot("close_"+model,pos,target);}}finally{UnityEngine.Object.DestroyImmediate(light);EditorSceneManager.OpenScene(s.path);}return new{images=5,temporaryInspectionLight=true};}
 public static object BakeStatus(){var s=SceneManager.GetActiveScene();var result=new{running=StaticOcclusionCulling.isRunning,bytes=StaticOcclusionCulling.umbraDataSize};if(!result.running){if(s.isDirty)EditorSceneManager.SaveScene(s);File.WriteAllText(O+"occlusion_result.json",JsonConvert.SerializeObject(result,Formatting.Indented));}return result;}
}
